 text(frame,48,sy+flowHeight+25,1460,"근거  "+evidence.slice(0,3).map(p=>p.split("/").pop()).join(" · "),15,false,"#6e7c8d");
 let y=imageY;
 box(frame,1580,y,672,46,"#202832","#202832");
